BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE r uuid; other_r uuid; a uuid; b uuid; d uuid; other_item uuid; c uuid; c2 uuid; v integer; n integer; blocked boolean;
BEGIN
 INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-RECEPTION-LINK-'||gen_random_uuid(),current_date,'TEST RECEPTION LINK','margin','TEST ONLY') RETURNING id INTO r;
 INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-OTHER-'||gen_random_uuid(),current_date,'TEST RECEPTION LINK','margin','TEST ONLY') RETURNING id INTO other_r;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,0,'RMA',10000) RETURNING id INTO a;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,1,'New',20000) RETURNING id INTO b;
 c:=public.create_reception_supplier_rma(r,'test@example.invalid');
 IF (SELECT count(*) FROM public.supplier_rma_items WHERE case_id=c)<>1 THEN RAISE EXCEPTION 'Existing overview not copied'; END IF;
 IF public.create_reception_supplier_rma(r,'test@example.invalid')<>c THEN RAISE EXCEPTION 'Repeated create duplicated dossier'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 UPDATE public.refurb_reception_items SET refurb_status='RMA' WHERE id=b;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=b AND expected_cents=20000) THEN RAISE EXCEPTION 'Later RMA not added with expected price'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_cases WHERE id=c AND version=v+1) THEN RAISE EXCEPTION 'Concurrent edit version not invalidated'; END IF;
 UPDATE public.refurb_reception_items SET refurb_status='RMA Submitted',compensation_cents=15000 WHERE id=b;
 IF (SELECT count(*) FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=b)<>1 THEN RAISE EXCEPTION 'Duplicate item'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=b AND expected_cents=20000) THEN RAISE EXCEPTION 'Existing dossier expectation overwritten'; END IF;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,2,'RMA',0) RETURNING id INTO d;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=d AND expected_cents=0) THEN RAISE EXCEPTION 'Inserted RMA or zero price not attached'; END IF;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(other_r,0,'RMA',30000) RETURNING id INTO other_item;
 IF EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE reception_item_id=other_item) THEN RAISE EXCEPTION 'Other reception automatically attached'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 blocked:=false; BEGIN PERFORM public.manage_supplier_rma('add_items',jsonb_build_object('case_id',c,'version',v,'item_ids',jsonb_build_array(other_item)),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_RECEPTION_MISMATCH' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Other reception manually attached'; END IF;
 IF (SELECT count(*) FROM public.supplier_rma_history WHERE case_id=c AND event='auto_add_item')<>2 THEN RAISE EXCEPTION 'Automatic linkage audit missing'; END IF;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c,'version',v,'stage','refunded'),'test@example.invalid');
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,3,'RMA',5000) RETURNING id INTO d;
 IF EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE reception_item_id=d) THEN RAISE EXCEPTION 'Closed dossier silently changed'; END IF;
 c2:=public.create_reception_supplier_rma(r,'test@example.invalid');
 IF c2=c OR (SELECT count(*) FROM public.supplier_rma_items WHERE case_id=c2)<>1 THEN RAISE EXCEPTION 'New dossier duplicated historic items'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_cases WHERE id=c AND stage='refunded') THEN RAISE EXCEPTION 'Refunded dossier reopened'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c2;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c2,'version',v,'stage','closed'),'test@example.invalid');
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents,description) VALUES(r,4,'Booked',7000,'ORIGINAL BOOKED DEVICE') RETURNING id INTO d;
 c2:=public.register_late_reception_rma(r,array[d],'test@example.invalid');
 IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=d AND refurb_status='Booked' AND price_cents=7000 AND rma_registered) THEN RAISE EXCEPTION 'Late booked RMA changed accounting'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE case_id=c2 AND reception_item_id=d) THEN RAISE EXCEPTION 'Late booked RMA not linked'; END IF;
 blocked:=false; BEGIN UPDATE public.refurb_reception_items SET price_cents=1 WHERE id=d; EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Booked price protection weakened'; END IF;
 blocked:=false; BEGIN UPDATE public.refurb_reception_items SET refurb_status='RMA' WHERE id=d; EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Booked status protection weakened'; END IF;
 blocked:=false; BEGIN DELETE FROM public.refurb_reception_items WHERE id=d; EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Booked delete protection weakened'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c2;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c2,'version',v,'stage','closed'),'test@example.invalid');
 c2:=public.register_late_reception_rma(r,array[d],'test@example.invalid');
 IF (SELECT count(*) FROM public.supplier_rma_items WHERE reception_item_id=d)<>2 THEN RAISE EXCEPTION 'Explicit repeat RMA after closure not supported'; END IF;
 blocked:=false; BEGIN PERFORM public.register_late_reception_rma(r,array[other_item],'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_RECEPTION_MISMATCH' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Forged reception selection accepted'; END IF;
END $$;
ROLLBACK;
SELECT 'PASS: reception create/open, automatic updates and inserts, deduplication, price snapshots, audit, isolation, closed history and new dossier; fixtures rolled back' as verification;
